module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] wptr, rptr, wptr_syn, rptr_syn;
    reg wen, ren;

    assign wptr_syn = wptr;
    assign rptr_syn = rptr;

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr <= 0;
        end else begin
            if (wen)
                wptr <= {wptr[ADDR_WIDTH-2:0], wptr[ADDR_WIDTH-1] ^ wptr[ADDR_WIDTH-2]};
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr <= 0;
        end else begin
            if (ren)
                rptr <= {rptr[ADDR_WIDTH-2:0], rptr[ADDR_WIDTH-1] ^ rptr[ADDR_WIDTH-2]};
        end
    end

    assign wen = winc && wrstn && !wfull;
    assign ren = rinc && rrstn && !rempty;

    always @(posedge wclk) begin
        if (wen)
            RAM_MEM[wptr_syn[ADDR_WIDTH-2:0]] <= wdata;
    end

    assign rdata = RAM_MEM[rptr_syn[ADDR_WIDTH-2:0]];

    assign wfull = (wptr_syn == {~rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
    assign rempty = (rptr_syn == wptr_syn);

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule
